#!/bin/bash
# Type-check both targets without launching Xcode.
#
# `swiftc -parse` only checks syntax — it happily accepts assigning to a shadowed
# `let`, calling a method that does not exist, or passing the wrong argument type.
# `-typecheck` runs the real type checker, which is what catches those. Use this
# before claiming a change compiles.
#
# The Core Data classes (Recording, GoalEntity, Session) and the asset symbols are
# generated by Xcode into build/.../DerivedSources, so a prior Xcode build must
# exist for them to be found. Without them you get spurious "cannot find type"
# errors from CoreDataModels.swift.
#
# Usage: scripts/typecheck.sh [ios|macos]      (default: both)

set -uo pipefail
cd "$(dirname "$0")/.."
PROJ="app/Kochi.xcodeproj/project.pbxproj"
STATUS=0

sources_for() { # $1 = Sources build-phase id
  python3 - "$1" <<'PY'
import re, sys, pathlib
s = pathlib.Path("app/Kochi.xcodeproj/project.pbxproj").read_text()
i = s.index(f"{sys.argv[1]} /* Sources */ = {{")
for n in re.findall(r"/\* ([^*]+?) in Sources \*/", s[i:s.index("};", i)]):
    if n.endswith(".swift"):
        print(n.split("/")[-1])
PY
}

check() { # $1=label $2=phase-id $3=sdk $4=target-triple $5=derived-sources-dir
  echo "==> $1"
  local files=() gen=() f h
  while read -r f; do
    h=$(find app/KochiApp -name "$f" -not -path '*/build/*' | head -1)
    [ -n "$h" ] && files+=("$h")
  done < <(sources_for "$2")

  if [ -d "$5" ]; then
    while read -r f; do gen+=("$f"); done < <(find "$5" -name '*.swift')
  else
    echo "    note: $5 missing — build once in Xcode so Core Data classes exist"
  fi

  echo "    ${#files[@]} sources + ${#gen[@]} generated"
  local out errs warns
  out=$(swiftc -typecheck \
      -sdk "$(xcrun --sdk "$3" --show-sdk-path)" \
      -target "$4" \
      -import-objc-header app/KochiApp/Kochi-Bridging-Header.h \
      "${files[@]}" "${gen[@]}" 2>&1)

  # Warnings count too. Xcode shows them, so silence here has to mean silence
  # there; only errors fail the run.
  errs=$(echo "$out" | grep -E "error:" | grep -v "^ *|")
  warns=$(echo "$out" | grep -E "warning:" | grep -v "^ *|")

  [ -n "$warns" ] && echo "$warns" | sed 's/^/    /'
  if [ -n "$errs" ]; then
    echo "$errs" | sed 's/^/    /'
    echo "    FAILED"
    STATUS=1
  elif [ -n "$warns" ]; then
    echo "    OK (with warnings)"
  else
    echo "    OK"
  fi
}

if [ "${1:-both}" != "macos" ]; then
  check "Kochi-iOS" 1B0000022 iphonesimulator arm64-apple-ios27.0-simulator \
        app/build/Kochi.build/Debug-iphonesimulator/Kochi-iOS.build/DerivedSources
fi
if [ "${1:-both}" != "ios" ]; then
  check "KochiApp (macOS)" 1A0000022 macosx arm64-apple-macos27.0 \
        app/build/Kochi.build/Debug/KochiApp.build/DerivedSources
fi

exit $STATUS
